<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center"><div><div class="text-overline">FINANCE</div><h1 class="text-h5 font-weight-bold">Payments</h1><div class="grey--text">Record and review customer collections.</div></div><v-spacer/><v-btn color="#165134" dark @click="dialog=true">Record Payment</v-btn></div></v-card><v-card flat><v-data-table :headers="headers" :items="items" :loading="loading"><template v-slot:item.amount="{item}"><b>{{money(item.amount)}}</b></template><template v-slot:item.status="{item}"><v-chip x-small dark color="success">{{item.status}}</v-chip></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="600"><v-card><v-card-title>Record Payment</v-card-title><v-card-text><v-row><v-col cols="12" md="6"><v-text-field v-model="form.booking_id" type="number" outlined dense label="Booking ID *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.customer_id" type="number" outlined dense label="Customer ID *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.amount" type="number" outlined dense label="Amount *"/></v-col><v-col cols="12" md="6"><v-select v-model="form.payment_method" :items="['cash','bank_transfer','cheque','online','other']" outlined dense label="Method *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.payment_date" type="date" outlined dense label="Payment Date *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.reference_number" outlined dense label="Reference #"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" outlined dense label="Notes"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text @click="dialog=false">Cancel</v-btn><v-btn color="#165134" dark :loading="saving" @click="save">Save Payment</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'Payments',data(){return{loading:false,saving:false,dialog:false,items:[],headers:[{text:'Receipt',value:'receipt_number'},{text:'Customer',value:'customer.name'},{text:'Booking',value:'booking.booking_number'},{text:'Amount',value:'amount'},{text:'Method',value:'payment_method'},{text:'Date',value:'payment_date'},{text:'Status',value:'status'}],form:{booking_id:null,customer_id:null,amount:null,payment_method:'cash',payment_date:new Date().toISOString().slice(0,10),reference_number:'',notes:''}}},mounted(){this.load()},methods:{async load(){this.loading=true;try{const r=await api.get('/payments',{params:{per_page:100}});this.items=r.data.data||[]}finally{this.loading=false}},money(v){return new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number(v||0))},async save(){this.saving=true;try{await api.post('/payments',this.form);this.dialog=false;await this.load()}catch(e){this.$root.$emit('show-error',e.response?.data?.message||'Unable to record payment.')}finally{this.saving=false}}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>